import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right columns and types
    if len(target_state) == 0:
        target_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        target_state = target_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Ensure cdc_events has the right types
    if len(cdc_events) == 0:
        cdc_events = pd.DataFrame(columns=["seq", "order_id", "op", "status", "amount", "event_ts"])
        cdc_events = cdc_events.astype({
            "seq": "int64",
            "order_id": "int64",
            "op": "str",
            "status": "str",
            "amount": "float64",
            "event_ts": "datetime64[us]"
        })

    # Step 1: Remove duplicate events (keep first occurrence of each seq)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Build a dict of current state for fast lookup
    state_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            oid = row["order_id"]
            state_dict[oid] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    # Step 3: Track which orders have been seen and their final event
    order_last_event = {}  # order_id -> (seq, op)

    # Sort events by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 4: Apply events in seq order with replay guard
    for _, event in cdc_events.iterrows():
        seq = event["seq"]
        order_id = event["order_id"]
        op = event["op"]
        status = event["status"]
        amount = event["amount"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in state_dict:
            if seq <= state_dict[order_id]["last_seq"]:
                continue

        # Apply the event
        if op in ("I", "U"):
            if order_id not in state_dict:
                # Create new row
                state_dict[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                # Update existing row
                state_dict[order_id]["status"] = status
                # For U with NULL amount, keep existing amount
                if op == "U" and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    state_dict[order_id]["amount"] = amount
                state_dict[order_id]["last_seq"] = seq
            order_last_event[order_id] = (seq, op)
        elif op == "D":
            if order_id in state_dict:
                del state_dict[order_id]
            order_last_event[order_id] = (seq, op)

    # Step 5: Build new_state from state_dict
    new_state_rows = []
    for order_id, state in state_dict.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": state["status"],
            "amount": state["amount"],
            "last_seq": state["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state = new_state.astype({
            "order_id": "int64",
            "status": "str",
            "amount": "float64",
            "last_seq": "int64"
        })

    # Step 6: Build tombstones for orders deleted in this batch
    # Tombstones: orders that had a row (in target or created) and last event is 'D'
    tombstone_rows = []

    # Orders that existed in target_state or were created/modified in events
    all_touched_orders = set(state_dict.keys()) | set(order_last_event.keys())

    for order_id in all_touched_orders:
        if order_id in order_last_event:
            seq, op = order_last_event[order_id]
            if op == "D":
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": seq
                })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones = tombstones.astype({
            "order_id": "int64",
            "deleted_seq": "int64"
        })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
